import itertools
COMP = {'A':'U','U':'A','G':'C','C':'G'}
def revcomp(s):
    return ''.join(COMP[c] for c in reversed(s))
def max_contig_comp(a,b):
    # max contiguous complementary stretch between a and revcomp(b) over any alignment
    rc = revcomp(b)
    best=0
    n=len(a); m=len(rc)
    for off in range(-(m-1), n):
        cur=0
        for i in range(max(0,off), min(n, off+m)):
            j=i-off
            if j<0 or j>=m: 
                cur=0; continue
            if a[i]==rc[j]:
                cur+=1; best=max(best,cur)
            else:
                cur=0
        cur=0
    return best
for i,j in itertools.combinations(range(len(loops)),2):
    m=max_contig_comp(loops[i],loops[j])
    if m>=4:
        print(f"L{i+1} vs L{j+1}: max contig comp = {m}")
